              XdrStellarValueExt(XdrStellarValueType.STELLAR_VALUE_BASIC),
            ),
            XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
            XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
            XdrUint32(0),
            XdrInt64(BigInt.zero),
            XdrInt64(BigInt.zero),
            XdrUint32(0),
            XdrUint64(BigInt.zero),
            XdrUint32(0),
            XdrUint32(0),
            XdrUint32(0),
            [
              XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
              XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
              XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
              XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
            ],
            XdrLedgerHeaderExt(0),
          ),
          XdrLedgerHeaderHistoryEntryExt(0),
        ),
        (XdrGeneralizedTransactionSet(1)
          ..v1TxSet = XdrTransactionSetV1(
            XdrHash(Uint8List.fromList(List<int>.filled(32, 0x00))),
            [],
          )),
        [],
        [],
        [],
        XdrUint64(BigInt.zero),
        [],
      ));
      expect(
        (original.toXdrJsonValue() as Map<String, Object?>).keys.single,
        'v2',
      );
      var json = original.toXdrJson();
      var fromDocument = XdrLedgerCloseMeta.fromXdrJson(json);
      expect(fromDocument.toXdrJson(), json);
      expect(
        fromDocument.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
      var fromTree = XdrLedgerCloseMeta.fromXdrJsonValue(
        original.toXdrJsonValue(),
      );
      expect(fromTree.toXdrJsonValue(), original.toXdrJsonValue());
      expect(
        fromTree.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
    });
    test('XdrLedgerCloseMeta rejects an undeclared discriminant', () {
      expect(
        () => XdrLedgerCloseMeta(3).toXdrJsonValue(),
        throwsA(isA<FormatException>()),
      );
    });
    test('XdrLedgerCloseMeta rejects an undeclared arm key', () {
      expect(
        () => XdrLedgerCloseMeta.fromXdrJsonValue(<String, Object?>{
          'xdr_json_undeclared_arm': null,
        }),
        throwsA(isA<FormatException>()),
      );
    });
  });
}
